// LEZ v0.4.0 public-side conformance (node --test, no network). The small vectors below are copied from the LEZ
// source test named in each test. The large fixture is generated by deploy/testnet/web/lez040-vectors/src/main.rs
// using v0.4.0's own crates; its field meanings are the generator's `parts`, `public_vector`, and `private_vector`.
import test from 'node:test';
import assert from 'node:assert/strict';
import { existsSync, readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import * as lez from '../lez040.js';
import { base64, sha256, schnorr } from '../vendor/noble.js';

const B = (a) => Uint8Array.from(a);
const H = lez.unhex;
const SEED = B([
  88, 189, 37, 237, 199, 125, 151, 226, 69, 153, 165, 113, 191, 69, 188, 221, 9, 34, 173,
  134, 61, 109, 34, 103, 121, 39, 237, 14, 107, 194, 24, 194, 191, 14, 237, 185, 12, 87, 22,
  227, 38, 71, 17, 144, 251, 118, 217, 115, 33, 222, 201, 61, 203, 246, 121, 214, 6, 187,
  148, 92, 44, 253, 210, 37,
]);
const AUX = new Uint8Array(32).fill(9);
const fixturePath = fileURLToPath(new URL('./fixtures/lez-v040-vectors.json', import.meta.url));
const fixture = existsSync(fixturePath) ? JSON.parse(readFileSync(fixturePath, 'utf8')) : null;
const withFixture = { skip: fixture ? false : 'waiting for lez-v040-vectors.json from the LEZ crates' };

test('key tree: keys_public.rs master_keys_generation', () => {
  assert.equal(lez.hex(lez.masterSecret(SEED)), '8e8c2c51ff9f83a3d243c6b02bf3a323f2c8e86345f03f1021680898f399b4a9');
});

test('key tree: keys_public.rs child_keys_generation, including hardened 2^31+13', () => {
  const child = lez.childSecret(lez.masterSecret(SEED), 2 ** 31 + 13);
  assert.equal(lez.hex(child), '707cf031af5f56a9b0b8b8fa0a098010c7558720974387e502e9894fdecd89f8');
  const node = lez.deriveNode(SEED, [2 ** 31 + 13]);
  assert.deepEqual(node.secret, child);
  assert.deepEqual(node.path, [2 ** 31 + 13]);
  assert.deepEqual(node.accountId, lez.publicAccountId(child));
  assert.equal(lez.pathString(lez.parsePath('/0/3')), '/0/3');
  assert.throws(() => lez.childSecret(lez.masterSecret(SEED), 2 ** 32));
});

test('per-nonce key seeds: signing_keys.rs key_seed_known_answers', () => {
  const secret = new Uint8Array(32).fill(7);
  assert.equal(lez.hex(lez.keySeed(secret, 0, 0n)), '68256777fe99e612069c47cf884d5d3ca225b6caa113df93d847859c99cf5ab1');
  assert.equal(lez.hex(lez.keySeed(secret, 'schnorr', 1n)), '5994302e299bf9e059ce56b00574b1224032a9aa669243a8e1a8ba100eca0c43');
  assert.equal(lez.keySeed(secret, 0, 1n)[0], lez.keySeed(secret, 0, 1n)[0]);
  assert.notEqual(lez.hex(lez.signingKey(secret, 0n).sk), lez.hex(lez.signingKey(secret, 1n).sk));
});

