test('entire BIP-340 table: LEZ signature/bip340_test_vectors.rs', { skip: !existsSync(lezFile('lee/state_machine/src/signature/bip340_test_vectors.rs')) }, () => {
  const src = readFileSync(lezFile('lee/state_machine/src/signature/bip340_test_vectors.rs'), 'utf8');
  let checked = 0;
  for (const block of src.split('TestVector {').slice(1)) {
    const get = (field) => block.match(new RegExp(field + '[^"]*"([0-9A-F]+)"'))?.[1];
    if (!/seckey: Some/.test(block) || !/aux_rand: Some/.test(block) || !/verification_result: true/.test(block)) continue;
    const sig = lez.sign(H(get('seckey')), H(get('message')), H(get('aux_rand')));
    assert.equal(lez.hex(sig).toUpperCase(), get('signature'));
    checked++;
  }
  assert.ok(checked >= 4, `checked ${checked}`);
});

function lezFile(rel) {
  return fileURLToPath(new URL('../../../../../../upstream/lez-v0.4.0/' + rel, import.meta.url));
}

test('maps and sets: sorted/deduplicated actors, authorities, nonce-derived signers and u64 promotions', () => {
  const id1 = new Uint8Array(32).fill(2), id2 = new Uint8Array(32).fill(1);
  const a1 = { account: id1, program: new Uint8Array(32) }, a2 = { account: id2, program: new Uint8Array(32) };
  const bytes = lez.encodeMessage({
    actors: [{ actor: a1, authority: 'none' }, { actor: a2, authority: 'signer' }, { actor: a1, authority: 'none' }],
    promotions: [9n, 2n, 9n], privateSigners: [a1, a2, a1], to: a1, data: new Uint8Array(),
    nonces: [[id1, 1n], [id2, 2n], [id1, 1n]], fee: null, evidence: [],
  });
  const tx = lez.decodePublicTransaction(lez.concat(bytes, B([0, 0, 0, 0])));
  assert.deepEqual(tx.actors.map((a) => lez.hex(a.actor.account)), [lez.hex(id2), lez.hex(id1)]);
  assert.deepEqual(tx.authorizedAccounts.map(lez.hex), [lez.hex(id2), lez.hex(id1)]);
  assert.deepEqual(tx.promotions, [2n, 9n]);
  assert.deepEqual(tx.nonces.map((n) => lez.hex(n[0])), [lez.hex(id2), lez.hex(id1)]);
  assert.deepEqual(tx.privateSigners.map((a) => lez.hex(a.account)), [lez.hex(id2), lez.hex(id1)]);
});

test('conflicting duplicates are refused before signing, in either order (LEZ actor_map / nonce_map)', () => {
  const id = new Uint8Array(32).fill(3), a = { account: id, program: new Uint8Array(32) };
  for (const actors of [[{ actor: a, authority: 'none' }, { actor: a, authority: 'signer' }],
    [{ actor: a, authority: 'signer' }, { actor: a, authority: 'none' }]]) {
    assert.throws(() => lez.encodeMessage({ actors, to: a, data: B([]), nonces: [[id, 1n]], fee: null, evidence: [] }),
      /refused before signing: an actor is declared twice with different authorities/);
  }
  for (const nonces of [[[id, 1n], [id, 2n]], [[id, 2n], [id, 1n]]]) {
    assert.throws(() => lez.encodeMessage({ actors: [{ actor: a, authority: 'signer' }], to: a, data: B([]), nonces, fee: null, evidence: [] }),
      /refused before signing: an account is given two different nonces/);
  }
  // An identical repeat gives the bytes of the single entry.
  const one = lez.encodeMessage({ actors: [{ actor: a, authority: 'signer' }], to: a, data: B([]), nonces: [[id, 1n]], fee: null, evidence: [] });
  const twice = lez.encodeMessage({ actors: [{ actor: a, authority: 'signer' }, { actor: a, authority: 'signer' }], to: a, data: B([]),
    nonces: [[id, 1n], [id, 1n]], fee: null, evidence: [] });
  assert.deepEqual(twice, one);
});

test('buildTransfer and buildCall: v0.4.0 authorities, keyed witnesses, rotation and decoding', () => {
  const from = lez.deriveNode(SEED, [0]), toNode = lez.deriveNode(SEED, [1]);
  const built = lez.buildTransfer({ from, to: toNode.accountId, toKey: lez.initialKey(toNode.secret),
    amount: 123456789n, nonce: 0n, gasLimit: 50000n, tip: 3n, maxFee: 999999n, aux: AUX });
  const decoded = lez.decodeWire(built.wire);
  assert.equal(decoded.kind, 'public');
  assert.equal(decoded.hash, built.hash);
  assert.equal(decoded.tx.entries[0].auth_data.length, 33 + 64 + 32);
  assert.deepEqual(decoded.tx.entries[0].auth_data.subarray(0, 33), lez.initialKey(from.secret));
  assert.deepEqual(decoded.tx.entries[0].next, lez.keyState(from.secret, 1n));
  const auth = decoded.tx.entries[0].auth_data;
  assert.ok(lez.verify(auth.subarray(33, 97), H(built.messageWithKeys), auth.subarray(97)));
  assert.deepEqual(decoded.tx.actors.map((a) => a.authority).sort(), ['none', 'signer']);
  assert.equal(lez.nativeTransferOf(decoded.tx).amount, 123456789n);
  assert.throws(() => lez.buildTransfer({ from, to: toNode.accountId, toKey: lez.initialKey(from.secret),
    amount: 1n, nonce: 0n, gasLimit: 1n, maxFee: 1n, aux: AUX }));
  const callActor = { account: new Uint8Array(32).fill(42), program: new Uint8Array(32).fill(50) };
  const call = lez.buildCall({ payer: from, to: callActor, actors: [callActor], data: B([1, 2]),
    nonce: 8n, gasLimit: 1000n, maxFee: 10000n, aux: AUX });
  assert.equal(lez.decodeWire(call.wire).tx.entries[0].auth_data.length, 96);
});

test('signEntries: witness_set.rs sign_orders_entries_by_account_and_signs_with_every_next_key', () => {
  const a = lez.deriveNode(SEED, [0]), b = lez.deriveNode(SEED, [1]);
  const message = lez.encodeMessage({
    actors: [a, b].map((n) => ({ actor: lez.nativeActor(n.accountId), authority: 'signer' })),
    to: lez.nativeActor(a.accountId), data: B([1]), nonces: [[a.accountId, 1n], [b.accountId, 2n]],
    fee: { payer: a.accountId, gasLimit: 10n, tip: 0n, maxFee: 100n }, evidence: [],
  });
  const signers = [{ secret: b.secret, nonce: 2n }, { secret: a.secret, nonce: 1n }];
  const entries = lez.signEntries(signers, message, 'public', [new Uint8Array(32).fill(1), AUX]);
  const sorted = signers.map((s) => ({ ...s, id: lez.publicAccountId(s.secret) })).sort((x, y) => lez.compareBytes(x.id, y.id));
  const keyed = lez.messageWithKeys(message, sorted.map((s) => lez.keyState(s.secret, BigInt(s.nonce) + 1n)), 'public');
  entries.forEach((entry, i) => {
    assert.deepEqual(entry.next, lez.keyState(sorted[i].secret, sorted[i].nonce + 1n));
    assert.ok(lez.verify(entry.auth_data.subarray(0, 64), keyed, entry.auth_data.subarray(64)));
  });
  assert.notDeepEqual(entries, lez.signEntries(signers, message, 'public', AUX));
});

function partsMessage(parts) {
  const actor = (a) => ({ account: H(a.account), program: H(a.program) });
  return {
    actors: parts.actors.map((a) => ({ actor: actor(a.actor), authority: a.authority })),
    promotions: parts.promotions.map(BigInt), privateSigners: parts.private_signers.map(actor),
    to: actor(parts.to), data: H(parts.data), nonces: parts.nonces.map(([id, n]) => [H(id), BigInt(n)]),
    fee: parts.fee && { payer: H(parts.fee.payer), gasLimit: BigInt(parts.fee.gas_limit),
      tip: BigInt(parts.fee.tip), maxFee: BigInt(parts.fee.max_fee) },
    evidence: parts.evidence.map((e) => e.key ? { key: H(e.key) } : {
      pda: { program: H(e.pda.program), seed: H(e.pda.seed) },
    }),
  };
}

test('fixture: every key-tree secret, per-nonce key/state and account id', withFixture, () => {
  assert.equal(fixture.lez.tag, 'v0.4.0');
  assert.equal(H(fixture.keys.seed).length, 64);
  for (const expected of fixture.keys.nodes) {
    const node = lez.deriveNode(H(fixture.keys.seed), lez.parsePath(expected.path));
    assert.equal(lez.pathString(node.path), expected.path);
    assert.equal(lez.hex(node.secret), expected.secret, expected.path);
    assert.equal(lez.hex(node.accountId), expected.account_id.hex, expected.path);
    assert.equal(lez.idToString(node.accountId), expected.account_id.base58, expected.path);
    assert.equal(lez.hex(lez.initialKey(node.secret)), expected.initial_key, expected.path);
    assert.deepEqual(node.accountId, lez.accountIdForInitialKey(H(expected.initial_key)));
    for (const k of expected.keys) {
      const nonce = BigInt(k.nonce), pair = lez.signingKey(node.secret, nonce);
      assert.equal(lez.hex(pair.sk), k.sk, `${expected.path}@${nonce}`);
      assert.equal(lez.hex(pair.pk), k.pk, `${expected.path}@${nonce}`);
      assert.equal(lez.hex(lez.keyCommitment(pair.pk)), k.key_commitment);
      const state = lez.keyState(node.secret, nonce);
      assert.equal(lez.hex(state), k.key_state);
      assert.equal(lez.hex(state), k.key_state_display);
      assert.equal(lez.hex(lez.keySeed(node.secret, 'schnorr', nonce)), lez.hex(lez.keySeed(node.secret, 0, nonce)));
    }
  }
});

test('fixture: every public message, keyed hash, witness and wrapper', withFixture, () => {
  for (const v of fixture.public) {
    const message = lez.encodeMessage(partsMessage(v.parts));
    assert.equal(lez.hex(message), v.message, `${v.name} message`);
    const next = v.next_keys.map(H);
    const keyed = lez.messageWithKeys(message, next, 'public');
    assert.equal(lez.hex(keyed), v.message_with_keys, `${v.name} keyed hash`);
    const entries = v.witness_entries.map((e) => ({ auth_data: H(e.auth_data), next: H(e.next) }));
    assert.deepEqual(entries.map((e) => e.next), next);
    v.signers.forEach((s, i) => {
      const nonce = BigInt(s.nonce), secret = H(s.secret), entry = entries[i], auth = entry.auth_data;
      const pair = lez.signingKey(secret, nonce);
      assert.deepEqual(entry.next, lez.keyState(secret, nonce + 1n));
      assert.equal(lez.hex(lez.publicAccountId(secret)), v.signer_ids[i]);
      assert.deepEqual(auth.subarray(-32), pair.pk);
      assert.ok(lez.verify(auth.subarray(-96, -32), keyed, pair.pk), `${v.name} signature ${i}`);
      assert.equal(auth.length, nonce === 0n ? 129 : 96);
      if (nonce === 0n) {
        assert.deepEqual(auth.subarray(0, 33), lez.initialKey(secret));
        assert.equal(lez.hex(lez.publicAccountId(secret)), v.signer_ids[i]);
      }
    });
    const tx = lez.encodePublicTransaction(message, entries);
    assert.equal(lez.hex(tx), v.tx, `${v.name} tx`);
    assert.equal(lez.hex(sha256(tx)), v.tx_hash);
    assert.equal(v.tx_hash, v.wire_hash);
    assert.equal(lez.hex(lez.concat(Uint8Array.of(0), tx)), v.lee_transaction);
    assert.equal(base64.encode(H(v.lee_transaction)), v.wire);
    assert.equal(lez.wrapPublic(tx).wire, v.wire);
    const decoded = lez.decodeWire(v.wire);
    assert.equal(decoded.kind, 'public');
    assert.equal(decoded.hash, v.tx_hash);
    assert.deepEqual(decoded.tx.bytes, tx);
    assert.equal(lez.hex(lez.encodeMessage(partsMessage(v.parts))), lez.hex(decoded.tx.messageBytes));
    const expectedParts = partsMessage(v.parts);
    assert.deepEqual({
      actors: decoded.tx.actors, promotions: decoded.tx.promotions, privateSigners: decoded.tx.privateSigners,
      to: decoded.tx.to, data: decoded.tx.data, nonces: decoded.tx.nonces,
      fee: decoded.tx.fee, evidence: decoded.tx.evidence,
    }, expectedParts, `${v.name} decoded parts`);
    assert.deepEqual(decoded.tx.authorizedAccounts, expectedParts.nonces.map(([id]) => id));
    assert.deepEqual(lez.decodePublicTransaction(tx).entries, entries);
  }
});

