function expectedReceipt(r) {
  const parsed = lez.parseJsonBig(r.json);
  return { success: parsed.success, fee: {
    gasExec: BigInt(parsed.fee.gas_exec), gasStor: BigInt(parsed.fee.gas_stor),
    feeBase: BigInt(parsed.fee.fee_base), tip: BigInt(parsed.fee.tip), refund: BigInt(parsed.fee.refund),
  } };
}

test('fixture: every block hash, transaction hash, reverted position and receipt', withFixture, () => {
  for (const b of fixture.blocks) {
    const d = lez.decodeBlock(b.json);
    assert.equal(lez.hex(d.bytes), b.borsh);
    assert.equal(d.header.hash, b.hash);
    assert.equal(d.computedHash, b.computed_hash ?? b.hash);
    assert.ok(d.hashOk);
    assert.deepEqual(d.transactions.map((t) => t.hash), b.tx_hashes ?? []);
    assert.deepEqual(d.reverted, b.reverted ?? []);
    assert.equal(d.status, 'Pending');
    b.tx_hashes?.forEach((hash, i) => assert.equal(lez.outcomeIn(d, hash), d.reverted.includes(i) ? 'reverted' :
      i >= d.receipts.length ? 'system' : 'applied'));
    assert.equal(lez.outcomeIn(d, '00'.repeat(32)), 'missing');
    d.receipts.forEach((receipt, i) => assert.deepEqual(receipt, expectedReceipt(fixture.receipts[i])));
  }
});

test('fixture: receipt JSON u128 values exactly match receipt borsh', withFixture, () => {
  for (const receipt of fixture.receipts) {
    const parsed = expectedReceipt(receipt), r = new lez.Reader(H(receipt.borsh));
    assert.equal(r.u8(), parsed.success ? 1 : 0);
    const borsh = { success: parsed.success, fee: {
      gasExec: r.u64(), gasStor: r.u64(), feeBase: r.u128(), tip: r.u128(), refund: r.u128(),
    } };
    assert.ok(r.end());
    assert.deepEqual(borsh, parsed);
  }
  const large = lez.parseJsonBig(fixture.receipts[1].json);
  assert.equal(typeof large.fee.fee_base, 'bigint');
  assert.equal(large.fee.fee_base, (1n << 64n));
});

test('parseJsonBig: only integer literals over 15 digits become bigint', () => {
  const text = '{"small":999999999999999,"large":1000000000000000,"negative":-1000000000000000,'
    + '"exponent":1e20,"float":1.2345678901234567,"string":"1000000000000000","array":[null,true,false]}';
  const j = lez.parseJsonBig(text);
  assert.equal(j.small, 999999999999999);
  assert.equal(typeof j.small, 'number');
  assert.equal(j.large, 1000000000000000n);
  assert.equal(j.negative, -1000000000000000n);
  assert.equal(j.exponent, JSON.parse('1e20'));
  assert.equal(j.float, JSON.parse('1.2345678901234567'));
  assert.equal(j.string, '1000000000000000');
  assert.deepEqual(j.array, [null, true, false]);
  const proto = lez.parseJsonBig('{"__proto__":{"polluted":false}}');
  assert.equal(Object.getPrototypeOf(proto), Object.prototype);
  assert.equal({}.polluted, undefined);
  assert.deepEqual(lez.parseJsonBig(' [ 1, {"x":"\\u0061"} ] '), [1, { x: 'a' }]);
  assert.throws(() => lez.parseJsonBig('[1,]'));
  assert.throws(() => lez.parseJsonBig('1x'));
  assert.throws(() => lez.parseJsonBig(' 1'));
});

test('negative: flipped auth_data signature fails; nonce-0 initial key cannot hide the flip', () => {
  const from = lez.deriveNode(SEED, [0]), to = lez.deriveNode(SEED, [1]);
  const built = lez.buildTransfer({ from, to: to.accountId, amount: 1n, nonce: 0n,
    gasLimit: 100n, maxFee: 1000n, aux: AUX });
  const entry = lez.decodePublicTransaction(built.txBytes).entries[0];
  const auth = entry.auth_data.slice(); auth[33] ^= 1;
  assert.equal(lez.verify(auth.subarray(33, 97), H(built.messageWithKeys), auth.subarray(97)), false);
});

test('negative: trailing bytes and unknown transaction tags are refused', () => {
  const from = lez.deriveNode(SEED, [0]), to = lez.deriveNode(SEED, [1]);
  const built = lez.buildTransfer({ from, to: to.accountId, amount: 1n, nonce: 2n,
    gasLimit: 100n, maxFee: 1000n, aux: AUX });
  assert.throws(() => lez.decodePublicTransaction(lez.concat(built.txBytes, B([0]))), /trailing bytes/);
  const wire = base64.decode(built.wire); wire[0] = 9;
  assert.throws(() => lez.decodeWire(base64.encode(wire)), /unknown transaction kind/);
  assert.throws(() => lez.decodeWire(base64.encode(lez.concat(base64.decode(built.wire), B([0])))), /trailing bytes/);
});

test('negative: trailing block bytes are refused and an altered stored hash gives hashOk false', () => {
  let bytes;
  if (fixture) bytes = base64.decode(fixture.blocks[0].json);
  else { // common/src/block.rs HashableBlockData::into_pending_block: an empty v0.4.0 block, then pin its own hash.
    bytes = new lez.Writer().u64(1n).raw(new Uint8Array(32)).raw(new Uint8Array(32)).u64(0n)
      .u32(0).u32(0).u8(0).done();
    bytes.set(H(lez.blockHashOf(bytes)), 40);
    assert.equal(lez.decodeBlock(base64.encode(bytes)).hashOk, true);
  }
  bytes = bytes.slice(); // Do not mutate the fixture's decoded buffer above.
  assert.throws(() => lez.decodeBlock(base64.encode(lez.concat(bytes, B([0])))), /trailing bytes/);
  const altered = bytes.slice(); altered[40] ^= 1;
  const block = lez.decodeBlock(base64.encode(altered));
  assert.equal(block.hashOk, false);
  assert.notEqual(block.computedHash, block.header.hash);
});

test('detectLezVersion: stub fetch answers v0.4.0, method-not-found and other failures', async (t) => {
  const responses = [
    { body: { jsonrpc: '2.0', id: 1, result: { state: 'online', height: 7, isOurTurn: true } }, expected: 'v0.4.0' },
    { body: { jsonrpc: '2.0', id: 1, error: { code: -32601, message: 'Method not found' } }, expected: 'pre-v0.4.0' },
  ];
  for (const { body, expected } of responses) {
    const fetch = t.mock.method(globalThis, 'fetch', async (_url, init) => {
      assert.equal(JSON.parse(init.body).method, 'getSequencerStatus');
      return new Response(JSON.stringify(body), { status: 200, headers: { 'Content-Type': 'application/json' } });
    });
    const seq = new lez.Sequencer('http://sequencer.test');
    assert.equal(await lez.detectLezVersion(seq), expected);
    assert.equal(fetch.mock.callCount(), 1);
    fetch.mock.restore();
  }
  // The rc3 gateway: HTTP 403 with the JSON-RPC -32601 body is rc3 (the body is read whatever the status).
  const gw = t.mock.method(globalThis, 'fetch', async () => new Response(
    '{"jsonrpc":"2.0","id":1,"error":{"code":-32601,"message":"method getSequencerStatus is not served by this gateway"}}', { status: 403 }));
  assert.equal(await lez.detectLezVersion(new lez.Sequencer('http://sequencer.test')), 'pre-v0.4.0');
  gw.mock.restore();
  // Another JSON-RPC error names no version: it is thrown, never read as rc3.
  const other = t.mock.method(globalThis, 'fetch', async () => new Response(
    '{"jsonrpc":"2.0","id":1,"error":{"code":-32603,"message":"Internal error"}}', { status: 200 }));
  await assert.rejects(() => lez.detectLezVersion(new lez.Sequencer('http://sequencer.test')), (e) => e instanceof lez.RpcError && e.code === -32603);
  other.mock.restore();
  // A stand-in answering every method with null names no version (v0.4.0's status is tagged by `state`).
  const nullFetch = t.mock.method(globalThis, 'fetch', async () =>
    new Response('{"jsonrpc":"2.0","id":1,"result":null}', { status: 200 }));
  await assert.rejects(() => lez.detectLezVersion(new lez.Sequencer('http://sequencer.test')), /version is unknown/);
  nullFetch.mock.restore();
  t.mock.method(globalThis, 'fetch', async () => { throw new Error('network down'); });
  await assert.rejects(() => lez.detectLezVersion(new lez.Sequencer('http://sequencer.test')), /network down/);
});

test('Sequencer.receipt preserves u128 JSON and returns null for an unknown hash', async (t) => {
  t.mock.method(globalThis, 'fetch', async (_url, init) => {
    const body = JSON.parse(init.body);
    assert.equal(body.method, 'getTransactionReceipt');
    return new Response(body.params[0] === 'unknown' ? '{"jsonrpc":"2.0","id":1,"result":null}' :
      '{"jsonrpc":"2.0","id":1,"result":{"success":true,"fee":{"gas_exec":5,"gas_stor":6,'
      + '"fee_base":340282366920938463463374607431768211455,"tip":18446744073709551616,"refund":0}}}',
    { status: 200 });
  });
  const seq = new lez.Sequencer('http://sequencer.test');
  assert.equal(await seq.receipt('unknown'), null);
  const receipt = await seq.receipt('known');
  assert.equal(receipt.fee.fee_base, (1n << 128n) - 1n);
  assert.equal(receipt.fee.tip, 1n << 64n);
  assert.equal(receipt.fee.gas_exec, 5);
});

// ---- blocks a real LEZ v0.4.0 sequencer served (LEZ's own standalone sequencer and wallet; fixture's `source`)
const realPath = fileURLToPath(new URL('./fixtures/lez-v040-standalone-blocks.json', import.meta.url));
const real = existsSync(realPath) ? JSON.parse(readFileSync(realPath, 'utf8')) : null;

test('a real v0.4.0 sequencer\'s blocks: hashes, the transfer LEZ\'s wallet sent, its receipt', { skip: !real }, () => {
  const b2 = lez.decodeBlock(real.blocks['2']);
  assert.ok(b2.hashOk);
  assert.equal(b2.receipts.length, 0);
  assert.deepEqual(b2.transactions.map((t) => lez.outcomeIn(b2, t.hash)), ['system', 'system']);
  const b3 = lez.decodeBlock(real.blocks['3']);
  assert.ok(b3.hashOk);
  assert.equal(String(b3.header.id), real.facts.transfer_block);
  const d = b3.transactions[0];
  assert.equal(d.hash, real.facts.transfer_tx);
  assert.equal(lez.outcomeIn(b3, d.hash), 'applied');
  const r = real.facts.transfer_receipt;
  assert.deepEqual(b3.receipts[0], { success: r.success, fee: { gasExec: BigInt(r.fee.gas_exec), gasStor: BigInt(r.fee.gas_stor),
    feeBase: BigInt(r.fee.fee_base), tip: BigInt(r.fee.tip), refund: BigInt(r.fee.refund) } });
  const n = lez.nativeTransferOf(d.tx);
  assert.equal('Public/' + lez.idToString(n.from), real.facts.test_account);
  assert.equal('Public/' + lez.idToString(n.to), real.facts.new_account);
  assert.equal(n.amount, BigInt(real.amount));
});

test('a real v0.4.0 transfer: this codec\'s keys sign as LEZ\'s wallet did, and buildTransfer rebuilds its message byte for byte', { skip: !real }, () => {
  const b3 = lez.decodeBlock(real.blocks['3']);
  const t = b3.transactions[0].tx;
  const secret = H(real.test_account_secret);
  assert.equal('Public/' + lez.idToString(lez.publicAccountId(secret)), real.facts.test_account);
  const auth = t.entries[0].auth_data;
  assert.equal(auth.length, 33 + 64 + 32, 'nonce 0: the initial key, then the signature and the key');
  assert.deepEqual(auth.subarray(0, 33), lez.initialKey(secret));
  assert.deepEqual(auth.subarray(97), lez.signingKey(secret, 0n).pk);
  assert.deepEqual(t.entries[0].next, lez.keyState(secret, 1n));
  const keyed = lez.messageWithKeys(t.messageBytes, t.entries.map((e) => e.next), 'public');
  assert.ok(lez.verify(auth.subarray(33, 97), keyed, auth.subarray(97)));
  // LEZ v0.4.0's wallet measured this transfer's fee (gas limit 0, max fee 8073) and named the new account by its
  // initial key: the same parts give the same message here.
  const built = lez.buildTransfer({ from: { secret, accountId: lez.publicAccountId(secret) },
    to: lez.idFromString(real.facts.new_account), toKey: t.evidence[0].key, amount: BigInt(real.amount), nonce: 0n,
    gasLimit: t.fee.gasLimit, tip: t.fee.tip, maxFee: t.fee.maxFee });
  assert.deepEqual(built.messageBytes, t.messageBytes);
  assert.equal(lez.wrapPublic(lez.encodePublicTransaction(t.messageBytes, t.entries)).hash, real.facts.transfer_tx);
});
